  /** Amount of high frequency detail. Depth needs to be greater than 0 for this to have an effect Default: 0.5. */
  get roughness(): H.Ref<number>;
  set roughness(v: H.In<number>);
  /** Amount of fine level detail present in the noise Range: 0 to 32767. Default: 0. */
  get depth(): H.Ref<number>;
  set depth(v: H.In<number>);
  /** Use the legacy way of generating noise. Has the issue that it can produce values outside of -1/1 Default: False. */
