/**
 * Settings for the file selection in Asset Browser mode
 *
 * bpy.types.FileAssetSelectParams
 */
export interface FileAssetSelectParams extends R.FileSelectParams {
  /**
   * Asset Library Default: 'ALL'.
   * - `ALL`: All Libraries (Show assets from all of the listed asset libraries)
   * - `LOCAL`: Current File (Show the assets currently available in this Blender session)
   * - `ESSENTIALS`: Essentials (Show basic building blocks and utilities coming with Blender)
   * - `ONLINE_ESSENTIALS`: Online Essentials (Show additional building blocks and utilities available online)
   * - `CUSTOM`: Custom (Show assets from the asset libraries configured in the Preferences)
   */
  get asset_library_reference(): H.Ref<"ALL" | "LOCAL" | "ESSENTIALS" | "ONLINE_ESSENTIALS" | "CUSTOM" | (string & {})>;
  set asset_library_reference(v: H.In<"ALL" | "LOCAL" | "ESSENTIALS" | "ONLINE_ESSENTIALS" | "CUSTOM" | (string & {})>);
  /** The UUID of the catalog shown in the browser Default: "". */
  get catalog_id(): H.Ref<string>;
  set catalog_id(v: H.In<string>);
  /**
   * Which assets to show based on catalog filter Default: 'ALL'.
   * - `ALL`: All (Show assets from all catalogs)
   * - `CATALOG`: Catalog (Show assets from the active catalog only)
   * - `UNASSIGNED`: Unassigned (Show assets not assigned to any catalog)
   */
  get asset_catalog_visibility(): H.Ref<"ALL" | "CATALOG" | "UNASSIGNED">;
  set asset_catalog_visibility(v: H.In<"ALL" | "CATALOG" | "UNASSIGNED">);
  /** Which asset types to show/hide, when browsing an asset library */
  get filter_asset_id(): H.Own<R.FileAssetSelectIDFilter>;
  /**
   * Determine how the asset will be imported Default: 'LINK'.
   * - `FOLLOW_PREFS`: Follow Asset or Preferences (Use the import method set in the Preferences for this asset library, don't override it for this Asset Browser)
   * - `LINK`: Link (Import the assets as linked data-block)
   * - `APPEND`: Append (Import the asset as copied data-block, with no link to the original asset data-block)
   * - `APPEND_REUSE`: Append (Reuse Data) (Import the asset as copied data-block while avoiding multiple copies of nested, typically heavy data. For example the textures of a material asset, or the mesh of an object asset, don't have to be copied every time this asset is imported. The instances of the asset share the data instead)
   * - `PACK`: Pack (Import the asset as linked data-block, and pack it in the current file (ensures that it remains unchanged in case the library data is modified, is not available anymore, etc.))
   */
  get import_method(): H.Ref<"FOLLOW_PREFS" | "LINK" | "APPEND" | "APPEND_REUSE" | "PACK" | (string & {})>;
  set import_method(v: H.In<"FOLLOW_PREFS" | "LINK" | "APPEND" | "APPEND_REUSE" | "PACK" | (string & {})>);
  /** Create instances for collections when linking, rather than adding them directly to the scene Default: False. */
  get instance_collections_on_link(): H.Ref<boolean>;
  set instance_collections_on_link(v: H.In<boolean>);
  /**
   * Choose the visibility of online and offline assets Default: 'ALL'.
   * - `ALL`: Online and Offline (Show assets that are both hosted online (need downloading) and available on disk already)
   * - `ONLY_ONLINE`: Online Only (Show only assets that need downloading (requires internet access))
   * - `ONLY_OFFLINE`: Offline Only (Show only assets that are available on disk already (no internet access needed))
   */
  get asset_access(): H.Ref<"ALL" | "ONLY_ONLINE" | "ONLY_OFFLINE">;
  set asset_access(v: H.In<"ALL" | "ONLY_ONLINE" | "ONLY_OFFLINE">);
  /** Create instances for collections when appending, rather than adding them directly to the scene Default: False. */
  get instance_collections_on_append(): H.Ref<boolean>;
  set instance_collections_on_append(v: H.In<boolean>);
}

