  set use_filter_movie(v: H.In<boolean>);
  /** Show script files Default: False. */
  get use_filter_script(): H.Ref<boolean>;
  set use_filter_script(v: H.In<boolean>);
  /** Show font files Default: False. */
  get use_filter_font(): H.Ref<boolean>;
  set use_filter_font(v: H.In<boolean>);
  /** Show sound files Default: False. */
  get use_filter_sound(): H.Ref<boolean>;
  set use_filter_sound(v: H.In<boolean>);
  /** Show text files Default: False. */
  get use_filter_text(): H.Ref<boolean>;
  set use_filter_text(v: H.In<boolean>);
  /** Show 3D volume files Default: False. */
  get use_filter_volume(): H.Ref<boolean>;
  set use_filter_volume(v: H.In<boolean>);
  /** Show folders Default: False. */
