  /** Exclude silhouette edges Default: False. */
  get exclude_silhouette(): H.Ref<boolean>;
  set exclude_silhouette(v: H.In<boolean>);
  /** Exclude border edges Default: False. */
  get exclude_border(): H.Ref<boolean>;
  set exclude_border(v: H.In<boolean>);
  /** Exclude crease edges Default: False. */
  get exclude_crease(): H.Ref<boolean>;
  set exclude_crease(v: H.In<boolean>);
  /** Exclude ridges and valleys Default: False. */
  get exclude_ridge_valley(): H.Ref<boolean>;
